"""Chapter 6: Methodology and Software Implementation for ParkSure.

methodology_blocks() is also rendered (renumbered) by document 9, application_blocks() by document 12; blocks() is the report chapter.
Numbers come from facts.py (experiments/**/metrics.json); formulas are exactly what app/engine.py and app/main.py compute.
"""

import os

from . import facts as F
from .appendix import _wrap
from .blocks import B, CODE as _CODE, EQ, FIG, H1, H2, H3, N, P, TAB
from .diagram_index import DIAGRAMS
from .refs import N as cite


def CODE(text, size=8.5):
    return _CODE(_wrap(text, 110), size)


_D = {k: (t, f, cap) for k, t, f, cap, _ in DIAGRAMS}


def _dg(key, caption=None, width=5.4):
    t, f, cap = _D[key]
    path = F.diag(f)
    return [FIG(path, caption or cap, width)] if os.path.exists(path) else []


def _fg(name, caption, width=5.6):
    path = F.fig(name)
    return [FIG(path, caption, width)] if os.path.exists(path) else []


def methodology_blocks():
    sc = F.SEED["status_counts"]
    mb = F.MB
    b = []

    # ------------------------------------------------------------------ 6.1
    b += [H2("6.1 Overall methodology"),
          P(f"ParkSure treats parking reservation as an admission-control problem with feedback. A request is a time interval at a location; the system admits it only if enough bays remain after the already admitted intervals and a hold-back buffer, "
            f"checks physical space when the driver arrives, and judges the departure afterwards. The punctuality of each departure feeds two memories, the location's buffer and the driver's Trust Score, which shape later admissions and prices. "
            f"The registered base paper {cite('base')} solves a different allocation problem (balancing passengers across zones), so the method follows the reservation, buffer and reward mechanism of {cite('cabri')} and builds the surrounding platform. The method has seven steps."),
          N("**Register and authenticate.** A driver registers with a name, e-mail and password (stored as a bcrypt hash) and receives a signed token; the first account on an empty database becomes the administrator.",
            "**Search.** For a chosen window, count the reserved and active bookings that overlap it at each location and report the bookable bays, which are capacity minus buffer minus overlapping bookings.",
            "**Reserve.** Refuse suspended drivers; admit the request only if overlapping bookings plus the buffer stay below the capacity; quote the fee; apply account credit; store the booking and the payment.",
            "**Pay.** Create a Stripe Checkout session in test mode, or the offline demo checkout when no key is configured; mark the payment paid on confirmation.",
            "**Arrive.** On check-in compare the bookings marked active at the location with its capacity. If the lot is full, book the single nearest other location whose own admission rule accepts the window, or mark the booking failed and credit the fee.",
            "**Depart.** On check-out decide on time (within ten minutes after the end) or late; grow the buffer after an on-time departure; record a benefit or a warning and update the Trust Score.",
            "**Analyse.** Replay the stored bookings under four buffer policies (Strategy Insights), and measure the rules with a simulator that was checked against the engine."),
          *_dg("algo", None, 5.2)]

    # ------------------------------------------------------------------ 6.2
    b += [H2("6.2 Dataset"),
          P("ParkSure is a rule-based system. **It has no machine-learning model and no external dataset**, so there is no training set, validation set or test set in the usual sense, and no dataset licence applies. "
            "Two kinds of data are used, and both are generated by the project itself."),
          P(f"The **demo database** is created on first start by `app/seed.py` with a fixed random seed (42). It contains {F.SEED['users']} users (one administrator and eight drivers, two of whom have an overstay history), {F.SEED['locations']} locations in Bengaluru coordinates "
            f"(20, 12, 15, 25 and 8 bays at 4.00, 3.00, 2.50, 5.00 and 2.00 dollars per hour), and {F.SEED['reservations']} reservations spread over the last 60 days plus eight Friday-evening peaks at the smallest lot, "
            f"which is deliberately over-subscribed so that the Strategy Insights page has contention to replay. Of the reservations, {sc['completed']} are completed, {sc['failed']} failed (unable to park) and {sc['declined']} declined; {F.SEED['payments']} payments are paid. "
            "**These records are synthetic.** They demonstrate the mechanism; they are not observations of real drivers, and no conclusion about real parking behaviour may be drawn from them."),
          TAB("The seeded demo database (fresh install, 2026-10-26).",
              ["Quantity", "Value"],
              [["Users", f"{F.SEED['users']} (1 admin, 8 drivers); initial trust 2 for drivers 3 and 6, 4 for drivers 1 and 2, 3 for the rest, 5 for the admin"],
               ["Locations", f"{F.SEED['locations']}: Central Station Garage (20 bays), Market Street Lot (12), Riverside Parking (15), Airport Express Park (25), Old Town Deck (8)"],
               ["Reservations", f"{F.SEED['reservations']}: {sc['completed']} completed, {sc['failed']} failed, {sc['declined']} declined, {sc['reserved']} reserved"],
               ["Payments", f"{F.SEED['payments']}, all paid, provider demo"],
               ["History", "60 days of 2 to 5 requests per day, plus 8 weekly Friday-evening bursts at Old Town Deck"],
               ["Split", "None: there is no model to train, so nothing is held out"]],
              widths=[1.4, 5.0], align=["l", "l"], size=10),
          P(f"The **simulator scenario** is the second data source. It re-creates the experiment of {cite('cabri')}: 8 parking areas of 10 bays, 80 to 110 vehicles, each making 10 parks of 1 to 3 hours, 25 to 50 percent of the vehicles leaving one hour late, and two stops of 8 to 16 hours outside the system. "
            "The base paper ran it in the SUMO traffic simulator " + cite("sumo") + "; ParkSure's simulator is a discrete-event program, not SUMO, and the parameters the paper does not state (arrival process, lead time, gaps, area choice) are assumptions listed in Section 6.6."),
          P("Seeded data are used for the product demonstration, the Strategy Insights replay and the screenshots. The simulator output is used for the buffer comparison in Chapter 8. Neither is real-world evidence, and each report section that uses them says so.")]

    # ------------------------------------------------------------------ 6.3
    b += [H2("6.3 Input handling and preprocessing"),
          P("There is no feature extraction, but every request is cleaned before it touches the rules. Four steps do that work."),
          B("**Schema validation (pydantic).** A name must have 2 to 120 characters, an e-mail must be valid, a password 6 to 128 characters; a location needs a latitude in [-90, 90], a longitude in [-180, 180], a capacity from 1 to 5,000, an hourly price from 0.50 to 100 and a buffer from 0 to 20; a reservation needs a location id of at least 1 and an end time later than the start time. A violation returns 422 with the offending field.",
            "**Normalisation.** E-mail addresses are stored in lower case and compared case-insensitively; every timestamp is made timezone-aware in UTC with `ensure_tz` before it is compared, so a naive time from the database and an aware time from the browser can never be mixed. The console sends ISO-8601 strings converted from the browser's local time.",
            "**Window rules.** A window is a half-open interval. Search and reservation reject windows longer than 30 days (400). Billing uses at least 0.25 hours, so a one-minute booking costs a quarter of an hour.",
            "**Seeding.** On first start the lifespan hook creates the tables and, if the location table is empty, runs the seeder described in Section 6.2. A repeated start does not seed again; deleting `parksure.db` restores the demo state."),
          P("Two things are not checked. A reservation may start in the past (the probe in Chapter 7 shows a window two days ago was accepted), and check-in is not restricted to the booked window (a booking 25 days ahead could be checked in at once). Both are listed as limitations.")]

    # ------------------------------------------------------------------ 6.4
    b += [H2("6.4 Algorithm choice and justification"),
          P("The literature offers several ways to allocate parking. The table below sets them against the requirements of this project: a general platform for ordinary urban lots, with a fixed price, no sensors, a response time in milliseconds and rules a driver can understand."),
          TAB("Alternatives considered and the reason for the choice.",
              ["Approach", "Source", "What it needs", "Decision for ParkSure"],
              [["Interval-overlap admission with a hold-back buffer", f"{cite('doulamis')}, {cite('cabri')}", "Booking intervals and a capacity", "Chosen: one count and one comparison per request; the buffer absorbs overstays"],
               ["Auction-based allocation (ASAP, MaPark, bidding)", f"{cite('asap')}, {cite('mapark')}, {cite('kokolaki')}", "Bidding agents or a central auctioneer", "Rejected: prices should be fixed and visible before booking"],
               ["Multi-objective integer programming", cite("mejri"), "Distances, congestion model, a solver", "Rejected: needs inputs and run time that an ordinary lot does not have"],
               ["Passenger-count grouping heuristics", cite("base"), "Passenger counts, sensing, zone structure", "Not adopted: solves zone load balancing inside one facility, a different problem"],
               ["Deposit to deter false bookings", cite("somani"), "Partial payment", "Not adopted: the Trust Score prices behaviour instead"],
               ["Nearest alternate by great-circle distance", f"{cite('cabri')}, {cite('safitri')}, {cite('sinnott')}", "Coordinates of each lot", "Chosen: no routing service, one decision, deterministic"]],
              widths=[1.8, 1.2, 1.5, 1.9], align=["l", "l", "l", "l"], size=9),
          P("**Why interval overlap.** Counting overlapping reservations is exact for the question 'will a bay be free at the start of this window if everyone leaves on time', it is linear in the number of bookings at one location, and it is the basic form of interval scheduling " + cite("kt") + ". "
            f"Its weakness is the one named by {cite('cabri')}: an overstaying driver breaks the assumption. **Why a buffer.** A buffer of bays that are never booked in advance but remain physically available turns that weakness into a controllable margin: a larger buffer refuses more requests and protects more arrivals. "
            "**Why one nearest alternate.** The paper argues that a second suggestion would usually be too far from the driver's destination; the code follows that rule. **Why a Trust Score.** A star rating that moves slowly (three benefits for a point, two warnings to lose one) gives a price signal and a last-resort sanction without any hardware. "
            "None of these choices is claimed to be optimal; Chapter 8 measures what each one does and where the shipped version departs from the paper.")]

    # ------------------------------------------------------------------ 6.5
    b += [H2("6.5 Mathematical formulation"),
          P("Let a location l have capacity C, buffer b and hourly price p. A booking r has window [s_r, e_r) and status in {reserved, active} while it holds a bay. For a request with window [s, e):"),
          EQ("O(l, s, e) = | { r at l : status(r) ∈ {reserved, active},  s_r < e,  e_r > s } |"),
          EQ("admit(l, s, e)  ⇔  O(l, s, e) + b < C          bookable(l, s, e) = max(0, C − b − O(l, s, e))"),
          P("The search route reports bookable(l, s, e) and the available flag (bookable > 0), which is equivalent to the admission inequality. The fee uses the duration h = (e - s) in hours and the multiplier m of the driver's rounded Trust Score τ:"),
          EQ("fee = round( max(0.25, h) × p × m(τ), 2 )        m = {0: 1.75, 1: 1.50, 2: 1.25, 3: 1.00, 4: 0.95, 5: 0.90}"),
          P("Account credit c is applied before payment: credit used = min(c, fee), amount due = fee minus credit used. On arrival at location l the engine counts the active bookings A(l) and, if A(l) ≥ C, selects the alternate with the smallest haversine distance " + cite("sinnott") + " among the locations whose own admission rule accepts the window:"),
          EQ("d = 2R · arcsin( √( sin²((φ₂ − φ₁)/2) + cos φ₁ · cos φ₂ · sin²((λ₂ − λ₁)/2) ) ),   R = 6371 km"),
          EQ("alternate = argmin d(l, l′)  over l′ ≠ l with admit(l′, s, e)        (none: booking fails, fee credited)"),
          P("At check-out at time t_out the departure is on time if t_out ≤ e + 10 minutes. With cap B_max = 5 and initial buffer b₀ = 1 the buffer update is b := min(b + 1, B_max) after an on-time departure, and b := b₀ once 24 hours have passed since the last reset (the scheduler checks every 30 minutes). "
            "The Trust Score τ, the benefit streak u and the warning count w, with B = 3, W = 2, τ in [0, 5] and the initial τ = 3, change as follows:"),
          EQ("on time:  u := u + 1;  if u ≥ 3 then τ := min(τ + 1, 5) and u := 0"),
          EQ("late:     u := 0;  w := w + 1;  if w ≥ 2 then τ := max(τ − 1, 0) and w := 0"),
          P("A driver is refused when the suspension cooldown is running, or when τ < 1.5 and a warning event was recorded within the last 14 days; in the second case a 24-hour cooldown is started. "
            "Because the check is repeated at every request and a refused request records no new benefit, a driver whose score has fallen below 1.5 cannot recover it by booking, so the practical lockout lasts until the last warning is 14 days old.")]

    # ------------------------------------------------------------------ 6.6
    b += [H2("6.6 Engine parameters, simulator and parity check"),
          P("In place of a trained model, ParkSure has a small set of policy parameters, all set in `app/config.py` and overridable by environment variables. They are fixed during every measurement in this report."),
          TAB("Policy parameters of the Smart Availability Engine.",
              ["Parameter", "Value", "Meaning"],
              [["BUFFER_INIT / BUFFER_MAX / BUFFER_RESET_HOURS", "1 / 5 / 24", "Initial buffer, cap, and the interval after which the scheduler resets it"],
               ["Scheduler interval", "30 minutes", "How often the reset job checks every location"],
               ["BENEFIT_STREAK_FOR_REWARD (B) / WARNINGS_FOR_PENALTY (W)", "3 / 2", "Benefits needed for +1 trust; warnings that cost -1"],
               ["TRUST_START / TRUST_MIN / TRUST_MAX", "3.0 / 0 / 5", "Trust range"],
               ["TRUST_SUSPEND_THRESHOLD / RECENT_VIOLATION_DAYS / SUSPEND_COOLDOWN_HOURS", "1.5 / 14 / 24", "Suspension rule"],
               ["FEE_MULTIPLIER", "1.75, 1.50, 1.25, 1.00, 0.95, 0.90", "Multiplier for trust 0 to 5"],
               ["On-time grace", "10 minutes", "Hard-coded in the check-out route"],
               ["Booking length limit", "30 days", "Hard-coded in `_require_future_window`"]],
              widths=[2.6, 1.5, 2.3], align=["l", "l", "l"], size=9.5),
          P("**Simulator configuration.** `scripts/parking_sim.py` is a discrete-event simulator with three event types: request, arrival and departure. It uses the engine's pure functions directly and re-implements the stateful rules (admission, trust update, suspension) on plain numbers. "
            "Each experimental cell runs 30 seeds (the paper used 5). The settings fixed before the runs were:"),
          TAB("Simulator settings and the assumptions the base paper does not state.",
              ["Setting", "Value"],
              [["Areas and bays", "8 areas x 10 bays, on a 4 x 2 grid 0.012 degrees (about 1.3 km) apart"],
               ["Population and behaviour", "80, 90, 100 or 110 vehicles (or a random 80 to 110); 25 to 50 percent leave one hour after the reserved end"],
               ["Parks per vehicle", "10, each planned for 1 to 3 hours; two stops of 8 to 16 hours outside the system"],
               ["Assumed by the project", "Reservation placed 15 to 60 minutes before arrival; next request 15 to 60 minutes after leaving; uniform choice of area; first request within 2 hours; every driver checks in on time"],
               ["Policies compared", "Static buffer 0, 1 and 3; dynamic as shipped (grows on an on-time departure); dynamic as in the paper (grows on a late departure); each with the Trust Score on or off"],
               ["Outcomes counted per run", "Refused by admission (no reservation), refused by suspension, moved to an alternate, alternate physically full, no park, success rate, bay utilisation"]],
              widths=[1.7, 4.7], align=["l", "l"], size=9.5),
          P(f"**Parity check.** A simulator is only evidence if it behaves like the product. `scripts/parity.py` feeds the same random inputs to the simulator's rules and to the real engine functions on an in-memory database and compares every decision: "
            f"{F.PAR['admission']['cases']:,} admission decisions, {F.PAR['trust']['cases']:,} trust updates and {F.PAR['suspension']['cases']} suspension decisions, {F.PAR['total_cases']:,} in all, with {F.PAR['total_mismatches']} mismatches. "
            f"The same check runs as {F.PYTEST_PARITY} tests in `tests/test_sim_parity.py`. What the parity check does not cover is the arrival and alternate logic, which the simulator mirrors by reading the code, and the scheduler's 30-minute granularity, which the simulator approximates by resetting at the first event after 24 hours."),
          P(f"**Cost of the decisions.** On an in-memory database with {F.MB['database'].split('= ')[1]}, the admission decision takes {mb['forecast_free (admission, 100 bookings at the location)']['mean_ms']} ms on average "
            f"(p95 {mb['forecast_free (admission, 100 bookings at the location)']['p95_ms']} ms), one haversine distance takes about a microsecond, and the nearest-alternate search over 49 other locations takes {mb['nearest_alternate over 49 other locations']['mean_ms']} ms "
            f"(p95 {mb['nearest_alternate over 49 other locations']['p95_ms']} ms) because it runs one overlap query per location.")]
    return b


def application_blocks():
    a, w = F.API_PORT, F.WEB_PORT
    b = []

    b += [H2("6.7 Application architecture"),
          P(f"The product is a single backend process and a browser console. The **FastAPI** application (`app/main.py`, port {a}) {cite('fastapi')} exposes the 22 routes and also serves the original vanilla pages from `static/`. The **React 19** console (port {w}, Vite) is the interface used in this report. "
            "SQLAlchemy 2 maps the five tables to SQLite " + cite("sqla") + "; APScheduler runs the buffer-reset job; python-jose signs the tokens; bcrypt hashes the passwords; the Stripe SDK creates Checkout sessions."),
          *_dg("arch", None, 5.4),
          P("The backend is organised around one idea: **a route does only HTTP work and the rules live in the engine**. Every route that changes data receives a database session through the `get_db` dependency, which opens a session per request and closes it afterwards. "
            "Protected routes add the `current_user` or `admin_user` dependency. The lifespan hook creates the tables, seeds an empty database and starts the scheduler, and stops it again on shutdown."),
          CODE("def forecast_free(db, loc, start, end) -> bool:\n"
               "    \"\"\"A slot will be free at arrival if overlapping bookings + buffer < capacity.\"\"\"\n"
               "    used = overlapping_count(db, loc.id, start, end)\n"
               "    return (used + loc.buffer_size) < loc.capacity", 8.5),
          P("The console reads the session from a React context. The token is kept in the browser's local storage (every access is wrapped in try/catch so a blocked storage only shortens the session); a single `api()` wrapper adds the bearer header, turns FastAPI error details into readable messages and reports status 0 when the server cannot be reached "
            "('Cannot reach the ParkSure server. Make sure the backend is running on port 8403.'). A 401 on an authenticated call clears the session. Pages are loaded lazily by route.")]

    b += [H2("6.8 API design"),
          P("Chapter 5 lists the 22 routes. This section shows the exchange that matters most, the reservation. The request is a three-field document. The response is the booking as the console displays it plus the payment information, so the page needs no second call. The exchange below was recorded from the running application on 2026-10-26 (Market Street Lot, two hours at 3.00 dollars an hour, a driver with Trust Score 3)."),
          CODE("POST /api/reservations        Authorization: Bearer <token>\n"
               "{ \"location_id\": 2, \"start_time\": \"2026-11-02T09:00:00+00:00\", \"end_time\": \"2026-11-02T11:00:00+00:00\" }\n\n"
               "200 OK\n"
               "{ \"id\": 355, \"location_id\": 2, \"location_name\": \"Market Street Lot\",\n"
               "  \"start_time\": \"2026-11-02T09:00:00+00:00\", \"end_time\": \"2026-11-02T11:00:00+00:00\",\n"
               "  \"status\": \"reserved\", \"fee\": 6.0, \"fee_multiplier\": 1.0,\n"
               "  \"checked_in_at\": null, \"checked_out_at\": null, \"decline_reason\": \"\", \"parent_id\": null,\n"
               "  \"payment_status\": \"pending\", \"payment_provider\": \"demo\",\n"
               "  \"credit_applied\": 0.0, \"amount_due\": 6.0,\n"
               "  \"checkout\": { \"url\": \"/api/payments/demo-confirm?session_id=demo_71d377a3e477&reservation_id=355\",\n"
               "                \"session_id\": \"demo_71d377a3e477\", \"provider\": \"demo\" },\n"
               "  \"stripe_configured\": false }", 8.0),
          P("When the window is full the same route answers with a conflict and stores a declined booking, so the refusal is visible on the administrator's overview:"),
          CODE("409 Conflict\n"
               "{ \"detail\": \"Kiosk Bay is fully reserved for the requested window (capacity 1, hold-back buffer 0). Please try another time or location.\" }", 8.0),
          P("The search route returns, for each location, the numbers the cards show: `capacity`, `buffer_size`, `overlapping`, `bookable` and `available`. The check-in route returns `{moved, reservation, message}` and, when the booking was moved, `alternate` and `distance_km`; "
            "when no alternate exists it returns `{moved: false, failed: true, reservation, message}`. The trust route returns the score, streak, warnings, `next_reward_in`, `fee_multiplier` and the last 20 events."),
          P(f"**Measured behaviour** (127.0.0.1, single process, SQLite, {F.LAT['requests_per_endpoint']} sequential requests per endpoint; Chapter 7 gives the full table): search {F.lat('GET /api/search'):.1f} ms mean, reservation {F.lat('POST /api/reservations'):.1f} ms, check-in {F.lat('POST /api/reservations/{id}/checkin'):.1f} ms, check-out {F.lat('POST /api/reservations/{id}/checkout'):.1f} ms, "
            f"login {F.lat('POST /api/auth/login'):.0f} ms (bcrypt cost 12, intentionally slow), the administrator's insights replay {F.lat('GET /api/admin/insights'):.0f} ms. "
            f"Two routes are slow because they build each row with two further queries: the driver's booking list ({F.lat('GET /api/reservations'):.0f} ms for about 400 stored rows) and the administrator's list of the 300 latest bookings ({F.lat('GET /api/admin/bookings'):.0f} ms). "
            f"Eight parallel clients reached {F.LAT['endpoints']['throughput_search_8_threads']['req_per_s']:.0f} search requests per second."),
          *_fg("f05_api_latency.png", "Measured mean and 95th-percentile response time of each endpoint (127.0.0.1, 200 sequential requests).", 5.4)]

    b += [H2("6.9 Security and error handling"),
          P("ParkSure is a multi-user application and its security model is correspondingly larger than a single-user tool's. We list what exists, and then what the project's own probes found missing."),
          B("**Passwords.** Hashed with bcrypt (cost 12) " + cite("bcrypt") + "; the plain password is never stored or logged. A failed login returns the same message for an unknown e-mail and a wrong password.",
            "**Sessions.** A JSON Web Token " + cite("jwt") + " signed with HS256 carries the user id, the role and a 12-hour expiry. Authorisation does not trust the role claim: `admin_user` reads the role from the database on every request.",
            "**Role guards and ownership.** Eight routes need a login and eight need the admin role (the five administrator routes and the three location-management routes). A driver who asks for another driver's booking gets 404, not 403, so the existence of a booking is not revealed.",
            "**Input validation.** pydantic limits on every body (Section 6.3); the ORM uses bound parameters, so the injection payloads tried in Chapter 7 returned 422 and no server error.",
            "**Payments.** Card data never reaches ParkSure: Stripe Checkout hosts the form, and the webhook verifies the Stripe signature before marking a payment paid. Without keys the webhook route is inert and the offline demo checkout is used.",
            "**Failure behaviour.** Business refusals are stored (declined, failed) and answered with a specific status and message; unknown objects answer 404; the console shows the message verbatim and offers a retry."),
          P(f"**What the probes found.** Run against a throw-away database on 2026-10-26, and read together with the code, they showed eight weaknesses or gaps, which we report as facts. (1) `GET /api/payments/demo-confirm` is unauthenticated and marked a pending payment as paid. "
            f"(2) A token signed with the shipped default secret `parksure-dev-secret-change-in-production` was accepted for the administrator; the secret must be set with `PARKSURE_JWT_SECRET` in any real deployment. "
            f"(3) Thirty wrong passwords in a row were all answered 401 and the correct password then worked: there is no lockout or rate limit. "
            f"(4) A booking window two days in the past was accepted. (5) A booking 25 days ahead could be checked in at once. "
            f"(6) The cross-origin policy allows every origin. (7) A user name containing markup is stored verbatim; the React console escapes it when it renders. "
            f"(8) With {F.RACE['simultaneous_requests_per_trial']} simultaneous requests for a window that had exactly one bookable bay, {F.RACE['trials_with_overbooking']} of {F.RACE['trials']} trials accepted two bookings, because the admission check and the insert are not one atomic step. "
            "None of these was changed in the product during this documentation; Chapter 9 lists them as known limitations and Chapter 10 the fixes (a database lock or unique slot rows, an authenticated payment callback, a required secret, a rate limiter, and window checks)."),
          P(f"The automated tests cover the role guards, the ownership rule, the validation errors, the 403 and 409 refusals, the cancellation refund and the suspension path ({F.PYTEST_API} API tests and {F.PYTEST_ENGINE} engine tests, all passing).")]

    b += [H2("6.10 Installation and execution"),
          P("The project needs Python 3.11 or newer and Node.js 20 or newer. `requirements.txt` lists fastapi, uvicorn, sqlalchemy, pydantic with e-mail validation, pydantic-settings, python-jose, passlib with bcrypt, bcrypt, apscheduler, stripe, python-multipart, reportlab, playwright and httpx2. "
            "The measurements in this report were taken with Python 3.14.7 in the project's virtual environment, FastAPI 0.141.1, SQLAlchemy 2.0.52, bcrypt 5.0.0, APScheduler 3.11.3 and Node.js 24.19.0."),
          N("Open the folder `8.ProjectCode`. The ports (backend 8403, frontend 5403) are fixed in `run.bat` and `vite.config.js`; the policy and Stripe settings of `app/config.py` are read from environment variables (the backend does not read the `.env` file), and every one has a default, so none is required.",
            "Run `run.bat`. It checks Python and Node, creates `.venv` if absent, installs `requirements.txt`, runs `npm install` in `frontend/` if needed, starts the backend with uvicorn on 8403 and the Vite dev server on 5403 in two console windows, waits up to 60 seconds for both to answer, and opens the browser.",
            "Open http://127.0.0.1:5403 and sign in with `driver1@parksure.app` / `driver123` or `admin@parksure.app` / `admin123`, or register a new account.",
            "To start from the demo state again, stop the backend, delete `parksure.db` and start it again; the tables are re-created and re-seeded.",
            f"To check an installation run `python scripts/smoke_test.py` ({F.SMOKE_TOTAL} checks on a throw-away database) and `python -m pytest tests -q` ({F.PYTEST_TOTAL} tests; `pip install pytest` first)."),
          P("Appendix B gives the same instructions as a user guide with the screens. Two practical notes: the first start of `run.bat` takes several minutes because of the package downloads, and a fresh environment may install newer package versions than those recorded above, which is why the versions are listed. "
            "The Docker files run the backend and the original static pages only, not the React console.")]
    return b


def _trim(bl):
    """Report variant: the diagrams already appear in Chapter 5 and the result charts in Chapter 8, so only the text, tables and code are kept."""
    out = []
    for b in bl:
        if b[0] == "fig" and (os.sep + "diagrams" + os.sep in b[1] or os.path.basename(b[1]).startswith(("f05",))):
            continue
        out.append(b)
    return out


def blocks():
    bl = [H1("CHAPTER 6: METHODOLOGY AND SOFTWARE IMPLEMENTATION")] + methodology_blocks() + application_blocks()
    return _trim(bl) if F.REPORT else bl
